	if (m_state == 9 || m_state == 10)
		return false;

	bool can = false;

	for (ACTIVE_ANIM *active = blend->m_anims->Begin(); active != NULL; active = active->m_overlay)
		can = (active->m_anim->m_flags & 0x400) != 0;

