/* @socom-skeleton stub OKToJump__FP9CSealCtrl */
bool OKToJump(CSealCtrl *ctrl)
{
	/* 0x274250: head room for a jump. A 20-unit ray straight up from 1 above the head's
	 * model height (on the node's axis: model x/z 0, to world through the node) must hit
	 * nothing, or only a camera-type-1 poly; the ray runs with the seal's node inactive and
	 * the camera collide flag set (cleared again on both ends). ELF quirks kept: the
	 * controller's entity and the hit's poly are not NULL-tested. */
	CZSealBody *body = static_cast<CZSealBody *>(ctrl->m_entity);
	CPnt3D head;
	body->PartInSpace(body->m_head, NULL, &head, NULL);
	head.y += 1.0f;
	CPnt3D local(0.0f, head.y, 0.0f);
	CPnt3D from;
	body->m_node->m_matrix.Transform(&local, &from, 1);
	CPnt3D to(from.x, from.y + 20.0f, from.z);
	bool active = body->GetNode()->SetActive(false);
	zdb::SetCameraCollideFlagRequired(true);
	zdb::IntersectStruct *hit = zdb::CWorld::m_world->GetIntersect(&from, &to);
	body->GetNode()->SetActive(active);
	bool ok = hit == NULL || hit->m_poly->m_cameratype == 1;
	zdb::SetCameraCollideFlagRequired(false);
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("SEAL: jump head room from %.1f %.1f %.1f: %s%s", from.x, from.y, from.z, ok ? "ok" : "blocked",
		hit != NULL ? " (hit)" : "");
#endif
	return ok;
}

/* @socom-skeleton stub OKToStand__FP10CZSealBody */
bool OKToStand(CZSealBody *seal)
{
	/* 0x2740f0 (InStateCrouch): head room to stand up: a 7-unit ray straight up from 2
	 * above the head's model height, over the body's world position (not rotated), must hit
	 * nothing or only a camera-type-1 poly; run as OKToJump's (node inactive, camera collide
	 * flag set, cleared on both ends). ELF quirk kept: the hit's poly is not NULL-tested. */
	CPnt3D head;
	seal->PartInSpace(seal->m_head, NULL, &head, NULL);
	head.y += 2.0f;
	CPnt3D from(0.0f, head.y, 0.0f);
	from.Add(seal->GetPosW(), &from);
	CPnt3D to(from.x, from.y + 7.0f, from.z);
	bool active = seal->GetNode()->SetActive(false);
	zdb::SetCameraCollideFlagRequired(true);
	zdb::IntersectStruct *hit = zdb::CWorld::m_world->GetIntersect(&from, &to);
	seal->GetNode()->SetActive(active);
	bool ok = hit == NULL || hit->m_poly->m_cameratype == 1;
	zdb::SetCameraCollideFlagRequired(false);
	return ok;
}

/* @socom-skeleton stub DropBody__10CZSealBodyFv */
void CZSealBody::DropBody()
{
	/* 0x274030 (WeaponHitAnim: a carrier killed): while carrying (state 9) the carried body
	 * is let go - detached, its blends popped down to the base (the last one, or the top,
	 * loses its control), no peek, falling dead forward (FallForward01) with its own world
	 * velocity as its in-air velocity; the carry ends. port: DetachBody is not written yet
	 * (carrying needs the unwritten action menu). */
	if (m_state != 9)
		return;

	CZSealBody *carried = m_carry;

	if (carried != NULL)
	{
		carried->DetachBody();
		CZBodyAnimBlend *top = carried->m_blends->Top();

		while ((u32)(carried->m_blends->m_top + 1) >= 2)
			top = carried->PopBlend();

		if (top != NULL)
			top->m_ctrl = 0;

		carried->m_desiredPeek = SEAL_PEEK::PEEK_NONE;
		carried->PushBlend((AnimType)AnimTypes::FallForward01, 8, false);
		carried->m_inAirHorizVel = carried->m_velW;
	}

	m_carry = NULL;
}

/* @socom-skeleton stub FlingBody__10CZSealBodyFPC6CPnt3Dff */
CZBodyAnimBlend * CZSealBody::FlingBody(const CPnt3D *from, float damage, float radius)
{
	/* 0x273bd0 (HandleDamageExplosive): a blast at `from` throws the body: nothing outside
	 * the radius (measured to the root part's height) or below 2 of falloff-scaled damage
	 * (1 - d^2/r^2). A carried body is dropped (falling forward). The stack is popped down to
	 * a stand, crouch or prone base anim, the top blend loses its control, no peek; prone
	 * bodies take "Prone cover", others fall away from the blast (backward when it comes
	 * from the front of the body). The push: gravity / 98.1 x damage in newtons x falloff /
	 * mass (at most 150) along the blast direction, added to the velocity; an upward push
	 * also sets the descent (at least the push, up to 3 x it for a flat push). Single
	 * player: stunned. Returns the fall blend. */
	CPnt3D pos = *GetPosW();
	pos.y += GetRootPart()->m_pos.y;
	CPnt3D dir;
	pos.Sub(from, &dir);
	f32 dist = dir.Normalize();

	if (!(dist < radius))
		return NULL;

	f32 falloff = 1.0f - dist * dist / (radius * radius);

	if (damage * falloff < 2.0f)
		return NULL;

	if (m_state == 9)
	{
		CZSealBody *carried = m_carry;

		if (carried != NULL)
		{
			carried->DetachBody();
			carried->ClearStack(1, true);
			carried->PushBlend((AnimType)AnimTypes::FallForward01, 8, false);
			carried->m_inAirHorizVel = carried->m_velW;
		}

		m_carry = NULL;
	}

	while (m_blends->m_top + 1 >= 2)
	{
		AnimType current = m_CurrentBlendAnimType;

		if (current == m_animset->BaseAnim((AnimType)1) || current == m_animset->BaseAnim((AnimType)18)
			|| current == m_animset->BaseAnim((AnimType)26))
			break;

		PopBlend();
	}

	m_blends->Top()->m_ctrl = 0;
	m_desiredPeek = SEAL_PEEK::PEEK_NONE;
	m_blends->Top(); /* ELF: read for nothing */
	s8 stance = m_state;
	CQuat inverse;
	inverse.vec.x = -m_quat.vec.x;
	inverse.vec.y = -m_quat.vec.y;
	inverse.vec.z = -m_quat.vec.z;
	inverse.w = m_quat.w;
	CPnt3D local;
	inverse.Apply(&dir, &local, 1);
	CZBodyAnimBlend *blend;

	if (stance == 2)
		blend = PushBlend(FindAnimType("Prone cover"), stance, false);
	else if (!(local.z <= 0.0f))
		blend = PushBlend((AnimType)AnimTypes::FallBackward01, stance, false);
	else
		blend = PushBlend((AnimType)AnimTypes::FallForward01, stance, false);

	f32 push = theCharacterDynamics.m_gravity / 98.100006f * (damage * theCharacterDynamics.m_DamageToNewtons) * falloff / m_mass;

	if (!(push <= 150.0f))
		push = 150.0f;

	f32 up = dir.y;
	dir.Scale(push, &dir);
	m_inAirHorizVel = m_velW;
	m_inAirHorizVel.Add(&dir, &m_inAirHorizVel);

	if (!(dir.y <= 0.0f))
	{
		f32 scale = 3.0f * (1.0f - up);

		if (scale < 1.0f)
			scale = 1.0f;

		m_descent = -dir.y * scale;
	}

	if (!theNetwork.m_bNetwork)
		m_am_stunned = 1;

#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("GREN: fling %s: dist %.1f of %.1f, push %.1f, blend %s", m_node != NULL && m_node->m_name != NULL ? m_node->m_name : "-",
		dist, radius, push, stance == 2 ? "prone cover" : !(local.z <= 0.0f) ? "fall backward" : "fall forward");
#endif
	return blend;
}

/* @socom-skeleton stub Jump__10CZSealBodyFv */
CZBodyAnimBlend * CZSealBody::Jump()
{
	/* 0x273a00: a local seal jumps only on the ground, after the jump timer, on a walkable
	 * slope, with head room (OKToJump); standing or crouched, not carrying, on a cycling
	 * blend: a jump in place (slow) or the launch (in the air state), keeping the world
	 * velocity in the air */
	bool remote = m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsRemote();

	if (!remote)
	{
		if (m_airborne || m_nextJumpTimer > 0.0f)
			return NULL;

		if (m_groundNormal.y < theCharacterDynamics.m_maxSlopeCos)
			return NULL;

		if (!OKToJump(static_cast<CSealCtrl *>(m_control)))
			return NULL;
	}

	CZBodyAnimBlend *top = m_blends->Top();
	s8 state = m_state;

	if (state == 2 || m_carry != NULL || state == 9 || state == 10)
		return top;

	m_last_foot = 2;

	if ((top->m_flags & 0x40) == 0)
		return NULL;

	f32 speed = sqrtf(m_velM.z * m_velM.z + m_velM.x * m_velM.x + m_velM.y * m_velM.y);
	CZBodyAnimBlend *blend;

	if (speed < 15.0f)
		blend = PushBlend((AnimType)AnimTypes::Jump, m_state, false);
	else
		blend = PushBlend(AnimType::animTypeJumpLaunch, 6, false);

	m_inAirHorizVel = m_velW;
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("SEAL: jump at %.1f %.1f %.1f, speed %.1f: %s", GetPosW()->x, GetPosW()->y, GetPosW()->z, speed,
		speed < 15.0f ? "in place" : "launch");
#endif
	return blend;
}

