/* @socom-skeleton stub PeekBaseState__10CZSealBodyFv */
SEAL_STATE CZSealBody::PeekBaseState()
{
	/* 0x273660: the state of the topmost blend that is not a peek (stand without one) */
	for (s32 i = m_blends->m_top; i >= 0; i--)
	{
		SEAL_STATE state = (SEAL_STATE)m_blends->m_stack[i]->m_state;

		if (state != SEAL_STATE::statePeek)
			return state;
	}

	return SEAL_STATE::stateStand;
}

/* @socom-skeleton stub BaseState__10CZSealBodyFv */
SEAL_STATE CZSealBody::BaseState()
{
	/* 0x2735f0: the stance of the topmost stand/crouch/prone blend (stand without one) */
	for (s32 i = m_blends->m_top; i >= 0; i--)
	{
		s8 state = m_blends->m_stack[i]->m_state;

		if (state == 0)
			return SEAL_STATE::stateStand;

		if (state == 1)
			return SEAL_STATE::stateCrouch;

		if (state == 2)
			return SEAL_STATE::stateProne;
	}

	return SEAL_STATE::stateStand;
}

/* @socom-skeleton stub ClearToBase__10CZSealBodyFb */
CZBodyAnimBlend * CZSealBody::ClearToBase(bool all)
{
	/* 0x273490: blends pop down to the stance base (stand / crouch / prone; all: one more
	 * while more than one is left); the top's control clears and the peek ends */
	while (m_blends->m_top + 1 > 1 && m_CurrentBlendAnimType != m_animset->BaseAnim(AnimType::animTypeStand)
		&& m_CurrentBlendAnimType != m_animset->BaseAnim(AnimType::animTypeCrouch)
		&& m_CurrentBlendAnimType != m_animset->BaseAnim(AnimType::animTypeProne))
	{
		PopBlend();
	}

	if (all && m_blends->m_top + 1 > 1)
		PopBlend();

	m_blends->Top()->m_ctrl = 0;
	m_desiredPeek = SEAL_PEEK::PEEK_NONE;
	return m_blends->Top();
}

